drop policy if exists memory_graph_nodes_select on public.memory_graph_nodes;
create policy memory_graph_nodes_select on public.memory_graph_nodes for select using (owner_scope='SYSTEM' or (owner_scope='USER' and user_id=(select auth.uid())) or (owner_scope='ORGANIZATION' and organization_id in(select om.organization_id from public.organization_memberships om where om.user_id=(select auth.uid()))));
drop policy if exists memory_graph_nodes_insert on public.memory_graph_nodes;
create policy memory_graph_nodes_insert on public.memory_graph_nodes for insert with check ((owner_scope='SYSTEM' and (select auth.role())='service_role') or (owner_scope='USER' and user_id=(select auth.uid())) or (owner_scope='ORGANIZATION' and organization_id in(select om.organization_id from public.organization_memberships om where om.user_id=(select auth.uid()))));
drop policy if exists memory_graph_nodes_update on public.memory_graph_nodes;
