drop policy if exists memory_graph_nodes_delete on public.memory_graph_nodes;
create policy memory_graph_nodes_delete on public.memory_graph_nodes for delete using ((owner_scope='SYSTEM' and (select auth.role())='service_role') or (owner_scope='USER' and user_id=(select auth.uid())) or (owner_scope='ORGANIZATION' and organization_id in(select om.organization_id from public.organization_memberships om where om.user_id=(select auth.uid()))));